CREATE OR REPLACE FUNCTION crm.normalizar_domicilio_legal(p_domicilio text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  -- Espacios exoticos que SI ocupan sitio: se convierten en espacio normal.
  v_espacios constant text := U&'\00A0\2007\202F\3000\1680\2000\2001\2002\2003\2004\2005\2006\2008\2009\200A\205F';
  -- Invisibles de ancho CERO y controles de direccion: no se normalizan, se
  -- RECHAZAN. Escritos con escapes Unicode a proposito — pegarlos literales
  -- volveria este fichero ilegible y no auditable.
  v_invisibles constant text :=
    U&'[\00AD\180E\200B\200C\200D\200E\200F\2028\2029\202A\202B\202C\202D\202E\2060\2061\2062\2063\2064\FEFF]';
  v_min constant int := 15;
  v_max constant int := 240;
  v_out text;
  v_plano text;
begin
  v_out := coalesce(p_domicilio, '');
  v_out := translate(v_out, v_espacios, repeat(' ', length(v_espacios)));
  v_out := btrim(regexp_replace(v_out, '\s+', ' ', 'g'));

  if v_out = '' then
    raise exception 'Completa el domicilio legal del cliente.'
      using errcode = '22023';
  end if;
  if v_out ~ v_invisibles then
    raise exception 'El domicilio legal contiene caracteres invisibles que no se imprimirian en el contrato.'
      using errcode = '22023';
  end if;
  -- length() sobre text cuenta CARACTERES, igual que el Array.from() del
  -- navegador.
  if length(v_out) not between v_min and v_max or v_out ~ '[[:cntrl:]]' then
    raise exception
      'El domicilio legal debe tener entre % y % caracteres válidos; escribe la calle, el número y el distrito.',
      v_min, v_max
      using errcode = '22023';
  end if;

  -- Al menos un digito. Los 19 domicilios reales de produccion lo cumplen sin
  -- excepcion, y es lo que separa una direccion de un relleno: `LIMA.`,
  -- `PENDIENTE`, `no tiene`, `Su casa` caen todos aqui.
  if v_out !~ '[0-9]' then
    raise exception
      'El domicilio legal necesita el número de la calle, el lote o la manzana.'
      using errcode = '22023';
  end if;

  -- Un unico caracter repetido: `.....`, `xxxxxxxxxxxxxxxx`, `----------------`.
  if length(regexp_replace(v_out, '[^[:alnum:]]', '', 'g')) > 0
     and (select count(distinct c) from regexp_split_to_table(
            regexp_replace(lower(v_out), '[^[:alnum:]]', '', 'g'), '') as t(c)) = 1 then
    raise exception 'El domicilio legal no puede ser un solo carácter repetido.'
      using errcode = '22023';
  end if;

  -- La direccion de la PROPIA Avance Corp. Se compara en plano (sin tildes, sin
  -- mayusculas, sin puntuacion) para que no la salve un acento o un «N.°».
  v_plano := lower(translate(v_out,
    'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'));
  v_plano := regexp_replace(v_plano, '[^a-z0-9 ]', '', 'g');
  v_plano := regexp_replace(v_plano, '\s+', ' ', 'g');
  if v_plano like '%republica de panama%' and v_plano like '%3635%' then
    raise exception
      'Esa es la dirección de Avance Corp, no la del cliente: el contrato dejaría a las dos partes domiciliadas en el mismo sitio.'
      using errcode = '22023';
  end if;

  return v_out;
end;
$function$

CREATE OR REPLACE FUNCTION private.inversion_datos_portal(p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_correo text; v_nombre text; v_domicilio text;
begin
  if jsonb_typeof(p_datos) is distinct from 'object' then
    raise exception 'Completa los datos para el acceso Avance de esta persona' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_object_keys(p_datos) k where k not in
    ('correo','nombre_completo','apellidos','nombres','telefono','domicilio'))
    or exists(select 1 from jsonb_each(p_datos) d where jsonb_typeof(d.value) not in ('string','null')) then
    raise exception 'El alta Avance contiene campos no admitidos; documento y responsable los determina el servidor' using errcode='22023';
  end if;
  v_correo:=lower(btrim(p_datos->>'correo'));
  v_nombre:=upper(btrim(p_datos->>'nombre_completo'));
  if v_correo is null or length(v_correo)>254 or v_correo !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or v_nombre is null or length(v_nombre) not between 2 and 240 or v_nombre ~ '[[:cntrl:]]' then
    raise exception 'Completa el nombre legal y un correo válido para el acceso Avance' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_each_text(p_datos) d where d.key in ('apellidos','nombres','telefono')
    and (length(d.value)>240 or d.value ~ '[[:cntrl:]]')) then
    raise exception 'Revisa los nombres y el teléfono del cliente' using errcode='22023';
  end if;
  v_domicilio:=crm.normalizar_domicilio_legal(p_datos->>'domicilio');
  return jsonb_build_object('correo',v_correo,'nombre_completo',v_nombre,
    'apellidos',nullif(upper(btrim(p_datos->>'apellidos')),''),
    'nombres',nullif(upper(btrim(p_datos->>'nombres')),''),
    'telefono',nullif(btrim(p_datos->>'telefono'),''),'domicilio',v_domicilio);
end;
$function$

CREATE OR REPLACE FUNCTION private.registrar_ajuste_si_mes_cerrado(p_lead_id uuid, p_motivo text, p_por uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$

declare
  v_lead        crm.leads%rowtype;
  v_periodo     date;
  v_acreditado  uuid;
  v_referido    boolean;
  v_peso        numeric;
  v_numerador   numeric;
  v_n_episodios integer;
  v_periodo_episodio date;
  v_pen         numeric := 0;
  v_usd         numeric := 0;
  v_detalle     jsonb := '[]'::jsonb;
  v_id          uuid;
begin
  select * into v_lead from crm.leads where id = p_lead_id;
  if not found or v_lead.convertido_en is null then
    return null;
  end if;

  v_periodo := date_trunc('month', v_lead.convertido_en at time zone 'America/Lima')::date;

  -- ⚠️ EL CERROJO, antes de mirar si el mes esta cerrado. Sin el, una anulacion
  -- concurrente con el sellado de ESE mes lee «abierto» —porque el sello aun no
  -- ha commiteado—, devuelve NULL, y el cierre anulado se queda pagado para
  -- siempre. Misma clave que en `crm.cerrar_periodo`.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('crm.periodos_cerrados'),
    (v_periodo - date '2000-01-01')::integer
  );

  -- Mes ABIERTO: no hay deuda que registrar. El mes se recalcula y el cierre
  -- desaparece de el, que es el comportamiento de siempre.
  if not exists (select 1 from crm.periodos_cerrados pc where pc.periodo = v_periodo) then
    return null;
  end if;

  -- A quien se le descuenta: el mismo acreditado que usa la cuota.
  v_acreditado := coalesce(
    (select ca.acreditado_a from crm.cierres_avance_anulados ca where ca.lead_id = p_lead_id),
    private.vendedor_acreditado_del_cierre(p_lead_id));
  if v_acreditado is null then
    -- Sin acreditado no hay a quien descontarle. No se inventa un deudor.
    return null;
  end if;

  -- Lo que valia el cierre en la conversion. El origen sale del LEDGER (la foto
  -- del episodio), no de `crm.leads.origen`, que es una columna viva.
  -- F6.c (v2, tras el P1 de Codex): EL EPISODIO MANDA. El cierre puede caer a
  -- caballo del mes (convertido_en usa now() de transaccion y el ledger
  -- statement_timestamp(), caso documentado): se localiza el episodio canonico
  -- del lead SIN depender del mes de leads.convertido_en, y de el salen el
  -- PERIODO real, el referido y el peso. Cero episodios => la sancion de
  -- conversion vale CERO (nunca 1 en silencio) y queda alerta; mas de uno =>
  -- excepcion de integridad (el ledger solo permite una conversion por lead).
  select count(*),
         coalesce(bool_or(e.fue_referido), false),
         min(date_trunc('month', (e.fecha_numerador at time zone 'America/Lima'))::date)
    into v_n_episodios, v_referido, v_periodo_episodio
  from private.conversion_episodios(
         '1900-01-01'::timestamptz, '2100-01-01'::timestamptz,
         null::date, true, '{}'::uuid[], 1) e
  where e.lead_id = p_lead_id and e.tipo = 'cierre';

  if v_n_episodios > 1 then
    raise exception 'Integridad: el lead % tiene % episodios de cierre en el ledger', p_lead_id, v_n_episodios;
  end if;
  if v_n_episodios = 1 and v_periodo_episodio is distinct from v_periodo then
    -- El mes REAL del cierre es el del episodio: el cerrojo y la foto del mes
    -- sellado se toman sobre ese periodo (se re-toma el candado por si acaso).
    v_periodo := v_periodo_episodio;
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtext('crm.periodos_cerrados'),
      (v_periodo - date '2000-01-01')::integer);
    if not exists (select 1 from crm.periodos_cerrados pc where pc.periodo = v_periodo) then
      return null;
    end if;
  end if;
  if v_n_episodios = 0 then
    insert into private.vigia_alertas (fase, motivo)
    values ('f6c_ajuste_sin_episodio',
            format('lead %s: sin episodio de cierre en el ledger; la sancion de conversion vale 0', p_lead_id));
  end if;

  v_peso := private.peso_referido_conversion(v_periodo);
  v_numerador := case when v_n_episodios = 0 then 0
                       when v_referido then v_peso else 1 end;

  -- ATR-4 (Miguel 31/08): «solo la conversion, siempre». La deuda de un mes
  -- sellado ya NO carga capital: el capital del analista se queda en su
  -- produccion y el de la empresa en el AUM. Solo se descuenta la conversion.
  v_pen := 0; v_usd := 0; v_detalle := '[]'::jsonb;

  -- Con capital siempre 0, la deuda existe SOLO si la conversion valia algo.
  -- numerador 0 (cierre sin episodio) => NULL POR DISENO declarado: el rastro
  -- queda en la alerta del vigia (f6c_ajuste_sin_episodio) y en la anulacion
  -- misma; no se fabrica una deuda vacia.
  if v_numerador <= 0 and v_pen = 0 and v_usd = 0 then
    return null;
  end if;

  insert into crm.ajustes_mes_cerrado (
    vendedor_id, periodo_origen, lead_id, motivo, creado_por,
    numerador, capital_pen, capital_usd, detalle,
    pendiente_numerador, pendiente_pen, pendiente_usd, pendiente_detalle
  ) values (
    v_acreditado, v_periodo, p_lead_id, p_motivo, p_por,
    v_numerador, v_pen, v_usd, v_detalle,
    v_numerador, v_pen, v_usd, v_detalle
  )
  on conflict (lead_id) do nothing
  returning id into v_id;

  return v_id;
end;

$function$

CREATE OR REPLACE FUNCTION public.actualizar_contrato(p_id uuid, p_contrato jsonb, p_cronograma jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_es_analista boolean := (select public.es_analista());
  v_es_gestor_cartera boolean := (select public.es_gestor_cartera());
  v_rol_crm text := private.rol_crm(v_uid);
  v_es_gerencia_crm boolean := coalesce(v_rol_crm = 'gerencia', false);
  v_es_crm_catalogado boolean :=
    coalesce(v_rol_crm in ('vendedor', 'supervisor'), false)
    and nullif(
      current_setting('crm.producto_condicion_id', true), ''
    ) is not null;
  v_row public.contratos%rowtype;
  v_cuota jsonb;
  v_numero text;
begin
  select *
    into v_row
  from public.contratos c
  where c.id = p_id;
  if not found then
    raise exception 'Contrato no encontrado' using errcode = 'P0002';
  end if;

  if v_es_gestor_cartera or v_es_gerencia_crm then
    -- P04 (2026-08-09): una membresía CRM REVOCADA prevalece sobre el poder de
    -- portal también para CORREGIR términos, no solo para la banca y el alta.
    -- Se pregunta por la revocación y NO por el guard bancario completo: ese
    -- exige cliente activo, y desactivar a un cliente no debe impedir corregir
    -- sus contratos históricos.
    if (select private.membresia_crm_revocada()) then
      raise insufficient_privilege using
        message = 'Tu membresia CRM fue revocada; no puedes corregir contratos';
    end if;
  elsif v_es_analista or v_es_crm_catalogado then
    if v_row.creado_por is distinct from v_uid then
      raise insufficient_privilege using
        message = 'Solo puedes corregir contratos que tu creaste';
    end if;
    if v_row.creado_en <= now() - interval '5 hours' then
      raise insufficient_privilege using
        message = 'La ventana de correccion de 5 horas ya vencio para este contrato';
    end if;
    if not (select private.puede_registrar_ventas()) then
      raise insufficient_privilege using
        message = 'Este cliente ya no esta en tu cartera; no puedes corregir su contrato';
    end if;
  else
    raise insufficient_privilege using message = 'No autorizado';
  end if;

  if v_row.estado in ('renovado', 'retirado')
     and not (select public.es_superadmin()) then
    raise exception
      'El contrato esta cerrado (%): no se pueden editar sus terminos',
      v_row.estado;
  end if;

  if (p_contrato->>'capital')::numeric < 100
     or (p_contrato->>'capital')::numeric > 100000000 then
    raise exception 'El capital debe estar entre 100 y 100,000,000';
  end if;
  if (p_contrato->>'tasa_anual')::numeric <= 0
     or (p_contrato->>'tasa_anual')::numeric > 50 then
    raise exception 'La tasa anual debe estar entre 0 y 50%%';
  end if;

  if (p_contrato->>'categoria') is not null
     and (p_contrato->>'categoria') not in (
       'nuevo', 'renovacion', 'upgrade'
     ) then
    raise exception 'Categoria invalida';
  end if;

  v_numero := nullif(btrim(p_contrato->>'numero_contrato'), '');
  if v_numero is not null
     and v_numero is distinct from v_row.numero_contrato then
    if exists (
      select 1
      from public.contratos c
      where c.numero_contrato = v_numero
        and c.id <> p_id
    ) then
      raise exception
        'El N de contrato % ya existe en otro contrato',
        v_numero;
    end if;
  end if;

  update public.contratos
     set numero_contrato = coalesce(v_numero, numero_contrato),
         capital = (p_contrato->>'capital')::numeric,
         moneda = coalesce(nullif(p_contrato->>'moneda', ''), moneda),
         tasa_anual = (p_contrato->>'tasa_anual')::numeric,
         modalidad = p_contrato->>'modalidad',
         tipo_interes = coalesce(
           nullif(p_contrato->>'tipo_interes', ''),
           tipo_interes
         ),
         fecha_inicio = (p_contrato->>'fecha_inicio')::date,
         fecha_vencimiento = (p_contrato->>'fecha_vencimiento')::date,
         notas_internas = nullif(
           btrim(coalesce(p_contrato->>'notas_internas', '')),
           ''
         ),
         categoria = coalesce(
           nullif(p_contrato->>'categoria', ''),
           categoria
         )
   where id = p_id;

  if p_cronograma is not null
     and jsonb_array_length(p_cronograma) > 0 then
    if not exists (
      select 1
      from public.cronograma_pagos cp
      where cp.contrato_id = p_id
        and (cp.estado = 'pagado' or cp.monto_pagado is not null)
    ) then
      delete from public.cronograma_pagos cp
      where cp.contrato_id = p_id;

      for v_cuota in
        select value from jsonb_array_elements(p_cronograma)
      loop
        insert into public.cronograma_pagos (
          contrato_id,
          numero_cuota,
          fecha_programada,
          monto_programado,
          estado,
          tipo
        ) values (
          p_id,
          (v_cuota->>'numero_cuota')::integer,
          (v_cuota->>'fecha_programada')::date,
          (v_cuota->>'monto_programado')::numeric,
          'pendiente',
          coalesce(nullif(v_cuota->>'tipo', ''), 'cuota')
        );
      end loop;
    else
      delete from public.cronograma_pagos cp
      where cp.contrato_id = p_id
        and not (cp.estado = 'pagado' or cp.monto_pagado is not null);

      for v_cuota in
        select je.value
        from jsonb_array_elements(p_cronograma) as je(value)
        where not exists (
          select 1
          from public.cronograma_pagos cp
          where cp.contrato_id = p_id
            and (cp.estado = 'pagado' or cp.monto_pagado is not null)
            and cp.numero_cuota = (je.value->>'numero_cuota')::integer
        )
      loop
        insert into public.cronograma_pagos (
          contrato_id,
          numero_cuota,
          fecha_programada,
          monto_programado,
          estado,
          tipo
        ) values (
          p_id,
          (v_cuota->>'numero_cuota')::integer,
          (v_cuota->>'fecha_programada')::date,
          (v_cuota->>'monto_programado')::numeric,
          'pendiente',
          coalesce(nullif(v_cuota->>'tipo', ''), 'cuota')
        );
      end loop;
    end if;
  end if;

  if p_contrato ? 'titulares' then
    perform public._sync_contrato_titulares(
      p_id,
      p_contrato->'titulares'
    );
  end if;

  return jsonb_build_object('id', p_id, 'ok', true);
end;
$function$
